{"cmd":"python3 - <<'PY'
from openpyxl import load_workbook
wb=load_workbook('/root/data/test-rar.xlsx')
ws=wb['Total Reserves']
# find columns for country names
countries=['Belarus','Georgia','Moldova','Ukraine','Uzbekistan','Czechia','Latvia','Lithuania','Slovakia']
cols={}
for col in range(1, ws.max_column+1):
    val=ws.cell(row=1, column=col).value
    if isinstance(val,str):
        for country in countries:
            if val.startswith(country+':') or val.startswith(country+' '):
                cols[country]=col
# Some names may differ: Czechia vs Czech Republic? In Total Reserves, row1 shows 'Czechia International Reserves (EOP, NSA, Mil.US$)' so starts with Czechia.
print('cols', cols)
# check 2025 row 18 values
for country in countries:
    col=cols.get(country)
    if col:
        val=ws.cell(row=18, column=col).value
        print(country, 'col', col, '2025', val)
    else:
        print(country, 'no column')
